protected function __construct(
        public int $jahr,
        public ?int $jahr2,
        public bool $archived,
        public bool $approvalEnd
    ) {
        // Migration: TFMFP-68
        if (!Tools::columnExists('massnahme', 'ident_ursprung')) {
            Tools::createColumn('massnahme', 'ident_ursprung', 'INT(11)', null, 'NULL');
        }
