            Tools::createColumn('teilmassnahme', 'ident_ursprung', 'INT(11)', null, 'NULL');
        }
    }

    /**
     * Gibt die Jahre des Gesamtplans als Text zurück.
     * (z.B: "2022" für einjährigen Gesamtplan, oder "2019 / 2020" für zweijährigen Gesamtplan.)
     * @param string $spacer Trennzeichenkette für zweijährigen Gesamtpläne
     * @return string Jahrestext
     */
    public function getJahreText(string $spacer = ' / '): string
    {
        return $this->jahr . ($this->jahr2 !== null ? $spacer . $this->jahr2 : '');
    }

